			ENDIF
			IF (ntc_bssfrom < 65536) && (ntc_bssfrom + ntc_bss_size > 42496)	; fwdref-ok
ntc_bss		equ 65536		; after Option Memory Reserved #A600-#FFFF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
